    } else if exists {
        "The model files are present but incomplete. Re-download them.".into()
    } else {
        "Model not downloaded yet.".into()
    };
    SpeechModelReady {
        id: id.to_string(),
        downloaded: exists,
        ready,
        message,
    }
}

