    let (_, kind) = crate::dictation::resolve_speech_model(&settings, &state.models_dir);
    let (loaded, engine_label) = match kind {
        crate::dictation::SpeechEngineKind::Fluid
        | crate::dictation::SpeechEngineKind::Sherpa

