pub fn resolve_speech_model_for_id(
    model_id: &str,
    settings: &crate::commands::Settings,
    models_dir: &std::path::Path,
) -> (std::path::PathBuf, SpeechEngineKind) {
    let entry = teletype_speech::catalog::find(model_id);
