            if present_allowed {
                assert!(c.model_present, "cell {} present", c.engine);
            } else {
                assert!(!c.model_present, "cell {} should be absent", c.engine);
                assert!(!c.should_run(), "cell {} should not run", c.engine);
            }
        }
    }

