    fn speech_pins_hold_against_hugging_face() {
        use teletype_speech::catalog::find;

        // (repo, file, bytes, sha256) for every pinned artifact, read from
        // the catalog entries.
        let mut all: Vec<(String, String, u64, String)> = Vec::new();

        // Qwen3-ASR: two GGUFs in ggml-org/Qwen3-ASR-1.7B-GGUF.
        if let Some(qwen) = find("qwen3-asr") {
            for a in qwen.artifacts() {
                if let Some(sha) = &a.sha256 {
                    all.push((
                        "ggml-org/Qwen3-ASR-1.7B-GGUF".to_string(),
                        a.file.clone(),
                        a.bytes,
                        sha.clone(),
                    ));
                }
            }
        }

        // Streaming ASR rows: one GGUF each in handy-computer repos.
        for id in [
            "nemotron-3.5-asr-streaming-q4",
            "moonshine-streaming-medium-q8",
            "granite-speech-470m-q4",
        ] {
            if let Some(m) = find(id) {
                let base = m.base_url().unwrap_or("");
                let repo = base
                    .strip_prefix("https://huggingface.co/")
                    .unwrap_or(base)
                    .split("/resolve/")
                    .next()
                    .unwrap_or(base);
                for a in m.artifacts() {
                    if let Some(sha) = &a.sha256 {
                        all.push((repo.to_string(), a.file.clone(), a.bytes, sha.clone()));
                    }
                }
            }
        }

        // Deduplicate repos so we only hit the tree API once per repo.
        let mut repos: Vec<String> = Vec::new();
        for (repo, _, _, _) in &all {
            if !repos.contains(repo) {
                repos.push(repo.clone());
            }
        }

        for repo in &repos {
            let url = format!("https://huggingface.co/api/models/{repo}/tree/main?recursive=true");
            let body = reqwest::blocking::get(&url)
                .expect("HF tree API request")
                .text()
                .expect("HF tree API body");
            let tree: serde_json::Value = serde_json::from_str(&body).expect("HF tree JSON");
            let items = tree.as_array().expect("HF tree is an array");
            for (r, file, bytes, sha) in all.iter().filter(|(r, _, _, _)| r == repo) {
                let entry = items
                    .iter()
                    .find(|e| e["path"].as_str() == Some(file.as_str()))
                    .unwrap_or_else(|| panic!("{file} is no longer in {r}"));
                assert_eq!(
                    entry["size"].as_u64(),
                    Some(*bytes),
                    "{file} size changed from the pin in {r}"
                );
                // The LFS oid is the sha256 of the resolved bytes.
                assert_eq!(
                    entry["lfs"]["oid"].as_str().map(|s| s.to_ascii_lowercase()),
                    Some(sha.to_ascii_lowercase()),
                    "{file} was republished; re-pin it ({r})"
                );
            }
        }
    }

    #[test]
    fn speech_file_already_installed_requires_the_pinned_digest_and_size() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("a.gguf");
        std::fs::write(&path, b"ggml").unwrap();
        let digest: &'static str = Box::leak(sha256_file(&path).unwrap().into_boxed_str());
        let spec = |sha: &'static str, bytes: u64| SpeechFileSpec {
            name: "a.gguf".into(),
            url: String::new(),
            dest: path.clone(),
            sha256: Some(sha),
            bytes,
        };
        assert!(
            speech_file_already_installed(&spec(digest, 4)),
            "the verified file must not be re-fetched"
        );
        assert!(
            !speech_file_already_installed(&spec(digest, 5)),
            "a size mismatch means the pin no longer describes this file"
        );
        assert!(
            !speech_file_already_installed(&spec("0".repeat(64).leak(), 4)),
            "a foreign digest must re-download"
        );
        assert!(
            !speech_file_already_installed(&SpeechFileSpec {
                name: "a.gguf".into(),
                url: String::new(),
                dest: dir.path().join("absent.gguf"),
                sha256: Some(digest),
                bytes: 4,
            }),
            "no file on disk is never already installed"
        );
    }

